// src/components/Sidebar.jsx
import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './Sidebar.css';

function Sidebar() {
  const [isOpen, setIsOpen] = useState(false);

  const toggleSidebar = () => {
    setIsOpen((prev) => !prev);
  };

  const closeSidebar = () => {
    setIsOpen(false);
  };

  return (
    <>
      {/* כפתור ההמבורגר – שלוש פסים בצד ימין למעלה */}
      <button
        className="menu-toggle"
        onClick={toggleSidebar}
        aria-label="פתיחת תפריט ניווט"
        >
        <span className={`menu-icon ${isOpen ? 'open' : ''}`}>
            <span className="menu-line" />
            <span className="menu-line" />
            <span className="menu-line" />
        </span>
    </button>


      {/* שכבת רקע מאחורה כשמופעל התפריט */}
      <div
        className={`sidebar-overlay ${isOpen ? 'open' : ''}`}
        onClick={closeSidebar}
      />

      {/* התפריט עצמו שנפתח מימין */}
      <aside className={`sidebar ${isOpen ? 'open' : ''}`}>
        <div className="sidebar-header">
          <h2>תפריט</h2>
          <p className="sidebar-subtitle">
            ניווט בין דוחות ועמודים
          </p>
        </div>

        <nav className="sidebar-nav">
          <Link to="/" onClick={closeSidebar}>דף הבית</Link>
          <Link to="/report1" onClick={closeSidebar}>דו״ח 1</Link>
          <Link to="/report2" onClick={closeSidebar}>דו״ח 2</Link>
          <Link to="/report3" onClick={closeSidebar}>דו״ח 3</Link>
          <Link to="/report4" onClick={closeSidebar}>דו״ח 4</Link>
          <Link to="/report5" onClick={closeSidebar}>דו״ח 5</Link>
        </nav>
      </aside>
    </>
  );
}

export default Sidebar;
